// Term lists for table version 1.
//
// DRAFT DATA, NOT A MEDICAL REFERENCE. Review before relying on it.
//
// Once cards have been printed with version 1, do NOT edit this file:
// token IDs are list positions and Huffman codes come from the frequencies,
// so any change would make old cards decode wrongly. Copy it to terms-v2.ts
// and bump FORMAT_VERSION instead.
//
// freq       rough relative frequency; higher = shorter Huffman code
// categories classes used for "this medication may conflict with an allergy"
// aliases    TRUE synonyms only (they decode to the main name)

export interface TermSpec {
  name: string;
  freq: number;
  categories?: string[];
  aliases?: string[];
}

